package com.onlinelibrary.controller;
import com.onlinelibrary.dao.impl.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/member/dashboard") public class MemberDashboardServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{long id=WebSupport.uid(r);var history=new TransactionDAOImpl().history(id);r.setAttribute("books",new BookDAOImpl().findAll());r.setAttribute("history",history);r.setAttribute("currentBorrowed",history.stream().filter(t->"BORROWED".equals(t.getStatus())||"OVERDUE".equals(t.getStatus())).count());r.setAttribute("searches",new SearchHistoryDAOImpl().findForMember(id));r.setAttribute("notifications",new NotificationDAOImpl().findForMember(id));r.setAttribute("unread",new NotificationDAOImpl().unreadCount(id));WebSupport.view(r,s,"member-dashboard.jsp");}catch(Exception e){WebSupport.fail(r,s,e);}}}
